import{b as a,a as o}from"./chunks/theme.wVadnyG9.js";import{_ as n,a as s,c as r,b as e,g as i,j as h}from"./chunks/framework.DVzkjf-b.js";const k=JSON.parse('{"title":"The Tests Passed. Who Won the Game?","description":"A rock-paper-scissors game, an overly helpful AI coach, and a classroom exercise for finding out what a learner can check on their own.","frontmatter":{"title":"The Tests Passed. Who Won the Game?","description":"A rock-paper-scissors game, an overly helpful AI coach, and a classroom exercise for finding out what a learner can check on their own.","socialImage":"/images/editorial/social-rock-paper.jpg","socialImageAlt":"Folded red paper covers a dark stone beside a strip of green check marks.","datePublished":"2026-11-25","dateModified":"2026-11-25"},"headers":[],"relativePath":"teaching/when-ai-helps-write-the-code.md","filePath":"teaching/when-ai-helps-write-the-code.md"}'),d={name:"teaching/when-ai-helps-write-the-code.md"};function c(l,t,p,u,m,g){return s(),r("div",null,[...t[0]||(t[0]=[e("h1",{id:"the-tests-passed-who-won-the-game",tabindex:"-1"},[i("The Tests Passed. Who Won the Game? "),e("a",{class:"header-anchor",href:"#the-tests-passed-who-won-the-game","aria-label":'Permalink to "The Tests Passed. Who Won the Game?"'},"​")],-1),e("p",{class:"article-deck"},"A rock-paper-scissors game taught me where an AI coach should stop talking.",-1),e("p",{class:"byline"},"Keith Williams · November 25, 2026",-1),e("figure",{class:"editorial-figure"},[e("img",{src:a,width:"1280",height:"853",alt:"Folded red paper covers a dark stone beside a strip of green check marks.",fetchpriority:"high"}),e("figcaption",null,"Paper covers rock. A green check tells you only what someone thought to test.")],-1),h('<p>Choose rock. The computer chooses paper. You know who won. The game I gave my web applications students at NJIT had no idea.</p><p>Twelve automated checks had passed on the starter. The page loaded. It could display a result if a test supplied one. It even knew how to explain that the game was unfinished. The function that had to <strong>decide</strong> who won was still a placeholder. You could read every green check as good news and still have to settle the round yourself. <a href="https://github.com/kaw393939/218_spec/blob/main/research/2026-10-25-rps-student-trial.md" target="_blank" rel="noreferrer">Inside the starter trial</a> · <a href="https://github.com/kaw393939/is218-rps-starter/blob/3983604d8e83de8fc9aadf792150df87e2961047/tests/test_shell.py" target="_blank" rel="noreferrer">What the tests checked</a></p><p>I left that hole on purpose. A coding agent could fill it in seconds. What I wanted to hear was a student saying, before anyone touched the code, <em>I picked rock. If the computer picks paper, the screen should tell me I lost.</em> That last word matters. A game can identify the winning move and still congratulate the wrong person.</p><h2 id="the-coach-that-kept-asking-why" tabindex="-1">The coach that kept asking why <a class="header-anchor" href="#the-coach-that-kept-asking-why" aria-label="Permalink to &quot;The coach that kept asking why&quot;">​</a></h2><p>I call these assignments Studios. A student makes something, tries it, and decides what to change. In the project folder is a plain-text file called <code>AGENTS.md</code>. It tells an AI coding assistant how to act during that particular lesson. A teacher can open the file, read the directions, and change them. One of the hardest directions to get right is when to wait.</p><p>I learned that from another Studio. In my introductory web course, students design a brand for a plain white T-shirt. To rehearse the assignment, I used a second AI to play a learner who kept answering “yes.” My coaching agent wanted a reason for the choice of audience. It asked. It rephrased. It asked again. The learner could have been unsure, tired, or ready to move on. My instructions had turned a reasonable question into a trap.</p><p>I changed the coach so it could offer one example and let the learner pause. A yes could approve a brand name. The reason the name fit a particular buyer could stay open until the learner had one. That rehearsal exposed a problem in my instructions. A simulated learner could help me find it. Only a classroom could tell me what real students would do next. <a href="https://github.com/kaw393939/is117-brand-studio/blob/main/docs/coaching-review-2026-10-25.md" target="_blank" rel="noreferrer">The coaching review</a></p><figure class="editorial-figure"><img src="'+o+'" width="1080" height="720" alt="An open hand gestures toward a worked example while a learner holds a pencil over a blank card." loading="lazy"><figcaption>The first card can show a method. The blank one gives the learner somewhere to start. Both editorial illustrations were generated with AI.</figcaption></figure><h2 id="change-one-thing-and-hand-over-the-keyboard" tabindex="-1">Change one thing and hand over the keyboard <a class="header-anchor" href="#change-one-thing-and-hand-over-the-keyboard" aria-label="Permalink to &quot;Change one thing and hand over the keyboard&quot;">​</a></h2><p>Consider what happens when the help goes away. In a randomized study, Judy Hanwen Shen and Alex Tamkin asked 52 developers to use an unfamiliar Python library. All 26 who had an AI assistant finished both tasks within the time limit. Twenty-two of the 26 working independently did. On an immediate quiz without AI, the assisted group averaged about four points lower out of 27. It was a short experiment with one library. But it asks a question I can use tomorrow. When class ends, which part can a student carry into the next problem? <a href="https://arxiv.org/html/2601.20245v3" target="_blank" rel="noreferrer">Read the revised study</a></p><p>In my content management course, the project is a tool that answers questions from a set of documents. For the first answer, the coach can ask the student to find the passage that supports it. For the next round, I can ask for a detail the documents leave out and hand the keyboard over. If I immediately say “check the source,” I’ve already made the most interesting decision for the student. Waiting leaves room for them to notice the missing evidence, ask for help, or surprise me with a better check. <a href="https://github.com/kaw393939/is373-rag/blob/main/docs/students/check.md" target="_blank" rel="noreferrer">Try the two-question exercise</a></p><p>That moment has a workplace counterpart. A customer sees “request received” and walks away. The engineer sitting beside them can ask what the person at the other end actually received. Switch to that person’s view. Find the request. Give them the keyboard. That is one piece of forward-deployed engineering I can bring into a classroom today.</p><h2 id="try-it-in-the-next-fifteen-minutes" tabindex="-1">Try it in the next fifteen minutes <a class="header-anchor" href="#try-it-in-the-next-fifteen-minutes" aria-label="Permalink to &quot;Try it in the next fifteen minutes&quot;">​</a></h2><p>The downloadable Studio starts with a question anyone can teach. A help desk changed its schedule. Five recorded waits used to be <strong>4, 5, 5, 6, and 30 minutes</strong>. Now they’re <strong>6, 6, 7, 7, and 9</strong>. Did service improve?</p><p>Give someone a moment with the numbers. The average fell from ten minutes to seven. The middle person waited seven minutes instead of five. Now introduce a visitor with ten minutes between classes. What would your learner check first? Listen for who raises the question of how long the appointment itself takes.</p><p>To adapt this for your class, open the teacher guide and paste it into an AI chat with one assignment you already teach. Ask it to help you build a Studio. Pick the decision you want students to own. Play a stuck student yourself. If the first hint gives the decision away, revise that line and try it again. The download includes a paper-based route. <strong>The ZIP is the teacher copy and contains answers. Give students only <code>LESSON.md</code> and <code>AGENTS.md</code>.</strong> <a href="/downloads/AI-Studio-Starter.zip">Download the teacher Studio</a> · <a href="https://github.com/kaw393939/kaw393939.github.io/blob/main/examples/ai-studio-starter/TEACHER-STUDIO.md" target="_blank" rel="noreferrer">Open the teacher guide</a></p><p>When students turn the work in, one revealing exchange is enough. They can choose a question that changed their work, point to the change, and show how they checked it. They can also mark a draft or explain the choice aloud. If the conversation already lives next to the fix, a link can spare everyone another reflection paper. <a href="/teaching/studio-field-notes">The classroom accounts and research behind the starter</a></p><p>The question I keep coming back to is one I’d also ask someone mentoring a new engineer. <strong>What do you ask on the first round that you hope they’ll ask for themselves on the second?</strong></p>',18)])])}const y=n(d,[["render",c]]);export{k as __pageData,y as default};
